import{_ as s,c as a,b as t,o as e}from"./app-kAzM2mI_.js";const l={};function i(p,n){return e(),a("div",null,[...n[0]||(n[0]=[t(`<h1 id="第二题" tabindex="-1"><a class="header-anchor" href="#第二题"><span>第二题</span></a></h1><hr><h3 id="公式1-最早达标孕周-text-ew-j" tabindex="-1"><a class="header-anchor" href="#公式1-最早达标孕周-text-ew-j"><span>公式1：最早达标孕周 ( \\text{EW}_j )</span></a></h3><ul><li><strong>公式内容</strong>：以阈值 ( \\tau ) 定义孕妇 ( j ) 的最早达标孕周，( \\text{EW}_j = \\min{ g: Y_j^{\\max}(g) \\geq \\tau } )；若不存在满足条件的 ( g )，则 ( \\text{EW}_j ) 记为缺失并在后续分割样本中剔除。</li><li><strong>变量说明</strong>： <ul><li>( \\tau )：用于定义最早达标孕周的阈值。</li><li>( j )：孕妇的索引。</li><li>( g )：孕周相关变量。</li><li>( Y_j^{\\max}(g) )：孕妇 ( j ) 在孕周 ( g ) 时的某一指标（文中未明确，结合上下文推测与达标相关）的最大值。</li><li>( \\text{EW}_j )：孕妇 ( j ) 的最早达标孕周。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_j = <span class="token function selector">\\min</span><span class="token function selector">\\{</span> g: Y_j^<span class="token punctuation">{</span><span class="token function selector">\\max</span><span class="token punctuation">}</span>(g) <span class="token function selector">\\geq</span> <span class="token function selector">\\tau</span> <span class="token function selector">\\}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="公式2-学习集-mathcal-d" tabindex="-1"><a class="header-anchor" href="#公式2-学习集-mathcal-d"><span>公式2：学习集 ( \\mathcal{D} )</span></a></h3><ul><li><strong>公式内容</strong>：学习集 ( \\mathcal{D} = { (x_j, \\text{EW}<em>j) }</em>{j=1}^n )（剔除缺失后）。</li><li><strong>变量说明</strong>： <ul><li>( \\mathcal{D} )：学习集。</li><li>( x_j )：孕妇 ( j ) 的 BMI 等特征变量。</li><li>( \\text{EW}_j )：孕妇 ( j ) 剔除缺失后的最早达标孕周。</li><li>( n )：学习集中样本的数量。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\mathcal</span><span class="token punctuation">{</span>D<span class="token punctuation">}</span> = <span class="token function selector">\\{</span> (x_j, <span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_j) <span class="token function selector">\\}</span>_<span class="token punctuation">{</span>j=1<span class="token punctuation">}</span>^n</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="公式3-分裂候选集-l-t-和-r-t" tabindex="-1"><a class="header-anchor" href="#公式3-分裂候选集-l-t-和-r-t"><span>公式3：分裂候选集 ( L(t) ) 和 ( R(t) )</span></a></h3><ul><li><strong>公式内容</strong>：对任意阈值 ( t )，把数据分为 ( L(t) = { j: x_j &lt; t } ) 和 ( R(t) = { j: x_j \\geq t } )。</li><li><strong>变量说明</strong>： <ul><li>( t )：用于分裂数据的阈值。</li><li>( L(t) )：特征 ( x_j ) 小于阈值 ( t ) 的样本索引集合。</li><li>( R(t) )：特征 ( x_j ) 大于等于阈值 ( t ) 的样本索引集合。</li><li>( x_j )：孕妇 ( j ) 的特征变量（如 BMI）。</li><li>( j )：样本索引。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">L(t) = <span class="token function selector">\\{</span> j: x_j &lt; t <span class="token function selector">\\}</span>, <span class="token function selector">\\quad</span> R(t) = <span class="token function selector">\\{</span> j: x_j <span class="token function selector">\\geq</span> t <span class="token function selector">\\}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="公式4-叶结点内预测-hat-mu-s" tabindex="-1"><a class="header-anchor" href="#公式4-叶结点内预测-hat-mu-s"><span>公式4：叶结点内预测 ( \\hat{\\mu}(S) )</span></a></h3><ul><li><strong>公式内容</strong>：叶结点内预测为该叶的样本均值，( \\hat{\\mu}(S) = \\frac{1}{|S|} \\sum_{j \\in S} \\text{EW}_j )。</li><li><strong>变量说明</strong>： <ul><li>( \\hat{\\mu}(S) )：叶结点 ( S ) 内的预测值。</li><li>( S )：叶结点包含的样本索引集合。</li><li>( |S| )：叶结点 ( S ) 内样本的数量。</li><li>( \\text{EW}_j )：样本 ( j ) 的最早达标孕周。</li><li>( j )：样本索引。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\hat</span><span class="token punctuation">{</span><span class="token function selector">\\mu</span><span class="token punctuation">}</span>(S) = <span class="token function selector">\\frac</span><span class="token punctuation">{</span>1<span class="token punctuation">}</span><span class="token punctuation">{</span>|S|<span class="token punctuation">}</span> <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>j <span class="token function selector">\\in</span> S<span class="token punctuation">}</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_j</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="公式5-平方误差代价-text-sse-s" tabindex="-1"><a class="header-anchor" href="#公式5-平方误差代价-text-sse-s"><span>公式5：平方误差代价 ( \\text{SSE}(S) )</span></a></h3><ul><li><strong>公式内容</strong>：平方误差代价 ( \\text{SSE}(S) = \\sum_{j \\in S} (\\text{EW}_j - \\hat{\\mu}(S))^2 )。</li><li><strong>变量说明</strong>： <ul><li>( \\text{SSE}(S) )：叶结点 ( S ) 内的平方误差代价。</li><li>( S )：叶结点包含的样本索引集合。</li><li>( \\text{EW}_j )：样本 ( j ) 的最早达标孕周。</li><li>( \\hat{\\mu}(S) )：叶结点 ( S ) 内的预测值。</li><li>( j )：样本索引。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>SSE<span class="token punctuation">}</span>(S) = <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>j <span class="token function selector">\\in</span> S<span class="token punctuation">}</span> (<span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_j - <span class="token function selector">\\hat</span><span class="token punctuation">{</span><span class="token function selector">\\mu</span><span class="token punctuation">}</span>(S))^2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="公式6-最优分裂阈值-t" tabindex="-1"><a class="header-anchor" href="#公式6-最优分裂阈值-t"><span>公式6：最优分裂阈值 ( t^* )</span></a></h3><ul><li><strong>公式内容</strong>：最优分裂阈值 ( t^* \\in \\arg\\min_t \\left[ \\text{SSE}(L(t)) + \\text{SSE}(R(t)) \\right] )，递归执行直至达到“最大叶结点数”或继续分裂无法显著降低代价。</li><li><strong>变量说明</strong>： <ul><li>( t^* )：最优的分裂阈值。</li><li>( \\arg\\min_t )：使后面表达式取得最小值的 ( t ) 的集合。</li><li>( \\text{SSE}(L(t)) )：分裂后左子集 ( L(t) ) 的平方误差代价。</li><li>( \\text{SSE}(R(t)) )：分裂后右子集 ( R(t) ) 的平方误差代价。</li><li>( t )：分裂阈值。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">t^* <span class="token function selector">\\in</span> <span class="token function selector">\\arg</span><span class="token function selector">\\min</span>_t <span class="token function selector">\\left</span><span class="token punctuation">[</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>SSE<span class="token punctuation">}</span>(L(t)) + <span class="token function selector">\\text</span><span class="token punctuation">{</span>SSE<span class="token punctuation">}</span>(R(t)) <span class="token function selector">\\right</span><span class="token punctuation">]</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_5-阈值圆整与-bmi-区间构造相关" tabindex="-1"><a class="header-anchor" href="#_5-阈值圆整与-bmi-区间构造相关"><span>（5）阈值圆整与 BMI 区间构造相关</span></a></h3><h4 id="公式1-阈值圆整" tabindex="-1"><a class="header-anchor" href="#公式1-阈值圆整"><span>公式1：阈值圆整</span></a></h4><ul><li><strong>公式内容</strong>：设从树中抽取的所有有效阈值集合为 ( \\mathcal{C} = { c_1, \\dots, c_K } )（升序），按固定步长 ( s )（代码中 ( s = 0.5 )）做“就近取整”并去重，( \\tilde{c}_k = \\text{round}\\left( \\frac{c_k}{s} \\right) \\cdot s )，并确保 ( \\tilde{c}_1 &lt; \\tilde{c}_2 &lt; \\dots &lt; \\tilde{c}_K )。</li><li><strong>变量说明</strong>： <ul><li>( \\mathcal{C} )：从树中抽取的有效阈值集合。</li><li>( c_k )：集合 ( \\mathcal{C} ) 中的第 ( k ) 个阈值。</li><li>( K )：阈值集合 ( \\mathcal{C} ) 中元素的个数。</li><li>( s )：固定步长，代码中为 ( 0.5 )。</li><li>( \\tilde{c}_k )：对 ( c_k ) 进行圆整后得到的阈值。</li><li>( \\text{round}(\\cdot) )：取整函数，将括号内的值四舍五入取整。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\tilde</span><span class="token punctuation">{</span>c<span class="token punctuation">}</span>_k = <span class="token function selector">\\text</span><span class="token punctuation">{</span>round<span class="token punctuation">}</span><span class="token function selector">\\left</span>( <span class="token function selector">\\frac</span><span class="token punctuation">{</span>c_k<span class="token punctuation">}</span><span class="token punctuation">{</span>s<span class="token punctuation">}</span> <span class="token function selector">\\right</span>) <span class="token function selector">\\cdot</span> s</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>并确保 ( \\tilde{c}_1 &lt; \\tilde{c}_2 &lt; \\dots &lt; \\tilde{c}_K )，LaTeX 表示为：</p><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\tilde</span><span class="token punctuation">{</span>c<span class="token punctuation">}</span>_1 &lt; <span class="token function selector">\\tilde</span><span class="token punctuation">{</span>c<span class="token punctuation">}</span>_2 &lt; <span class="token function selector">\\dots</span> &lt; <span class="token function selector">\\tilde</span><span class="token punctuation">{</span>c<span class="token punctuation">}</span>_K</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式2-bmi-分组区间" tabindex="-1"><a class="header-anchor" href="#公式2-bmi-分组区间"><span>公式2：BMI 分组区间</span></a></h4><ul><li><strong>公式内容</strong>：最终 BMI 分组为左闭右开区间 ( (-\\infty, \\tilde{c}_1), [\\tilde{c}_1, \\tilde{c}_2), \\dots, [\\tilde{c}_K, +\\infty) )（与 ( \\text{pd.cut}(..., \\text{right=False}) ) 一致）。</li><li><strong>变量说明</strong>： <ul><li>( \\tilde{c}_k )：经过圆整后的阈值，用于划分 BMI 区间。</li><li>( K )：阈值的个数，决定区间的数量。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">(-<span class="token function selector">\\infty</span>, <span class="token function selector">\\tilde</span><span class="token punctuation">{</span>c<span class="token punctuation">}</span>_1), <span class="token punctuation">[</span><span class="token function selector">\\tilde</span><span class="token punctuation">{</span>c<span class="token punctuation">}</span>_1, <span class="token function selector">\\tilde</span><span class="token punctuation">{</span>c<span class="token punctuation">}</span>_2), <span class="token function selector">\\dots</span>, <span class="token punctuation">[</span><span class="token function selector">\\tilde</span><span class="token punctuation">{</span>c<span class="token punctuation">}</span>_K, +<span class="token function selector">\\infty</span>)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="_6-组内统计量与建议时点相关" tabindex="-1"><a class="header-anchor" href="#_6-组内统计量与建议时点相关"><span>（6）组内统计量与建议时点相关</span></a></h3><h4 id="公式1-样本量-n-g" tabindex="-1"><a class="header-anchor" href="#公式1-样本量-n-g"><span>公式1：样本量 ( n_g )</span></a></h4><ul><li><strong>公式内容</strong>：对任一 BMI 组 ( g )，样本量 ( n_g = |g| )。</li><li><strong>变量说明</strong>： <ul><li>( g )：某一 BMI 组。</li><li>( n_g )：BMI 组 ( g ) 内的样本量。</li><li>( |g| )：表示集合 ( g ) 中元素的个数，即该组的样本数量。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">n_g = |g|</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式2-均值-overline-text-ew-g" tabindex="-1"><a class="header-anchor" href="#公式2-均值-overline-text-ew-g"><span>公式2：均值 ( \\overline{\\text{EW}}_g )</span></a></h4><ul><li><strong>公式内容</strong>：均值 ( \\overline{\\text{EW}}<em>g = \\frac{1}{n_g} \\sum</em>{j \\in g} \\text{EW}_j )。</li><li><strong>变量说明</strong>： <ul><li>( \\overline{\\text{EW}}_g )：BMI 组 ( g ) 内“最早达标孕周”的均值。</li><li>( n_g )：BMI 组 ( g ) 内的样本量。</li><li>( \\text{EW}_j )：样本 ( j ) 的“最早达标孕周”。</li><li>( j )：样本索引，( j \\in g ) 表示样本 ( j ) 属于 BMI 组 ( g )。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\overline</span><span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span><span class="token punctuation">}</span>_g = <span class="token function selector">\\frac</span><span class="token punctuation">{</span>1<span class="token punctuation">}</span><span class="token punctuation">{</span>n_g<span class="token punctuation">}</span> <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>j <span class="token function selector">\\in</span> g<span class="token punctuation">}</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_j</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式3-中位数-text-med-g" tabindex="-1"><a class="header-anchor" href="#公式3-中位数-text-med-g"><span>公式3：中位数 ( \\text{Med}_g )</span></a></h4><ul><li><strong>公式内容</strong>：中位数 ( \\text{Med}<em>g = \\text{EW}</em>{\\left( \\lceil n_g / 2 \\rceil \\right)} )。</li><li><strong>变量说明</strong>： <ul><li>( \\text{Med}_g )：BMI 组 ( g ) 内“最早达标孕周”的中位数。</li><li>( \\text{EW}_{\\left( \\lceil n_g / 2 \\rceil \\right)} )：将组内“最早达标孕周”排序后，位于第 ( \\lceil n_g / 2 \\rceil ) 位的数值，其中 ( \\lceil \\cdot \\rceil ) 是向上取整函数。</li><li>( n_g )：BMI 组 ( g ) 内的样本量。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>Med<span class="token punctuation">}</span>_g = <span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\left</span>( <span class="token function selector">\\lceil</span> n_g / 2 <span class="token function selector">\\rceil</span> <span class="token function selector">\\right</span>)<span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式4-最小值-min-g-和最大值-max-g" tabindex="-1"><a class="header-anchor" href="#公式4-最小值-min-g-和最大值-max-g"><span>公式4：最小值 ( \\min_g ) 和最大值 ( \\max_g )</span></a></h4><ul><li><strong>公式内容</strong>：最小值 ( \\min_g = \\text{EW}<em>{(1)} )，最大值 ( \\max_g = \\text{EW}</em>{(n_g)} )。</li><li><strong>变量说明</strong>： <ul><li>( \\min_g )：BMI 组 ( g ) 内“最早达标孕周”的最小值。</li><li>( \\max_g )：BMI 组 ( g ) 内“最早达标孕周”的最大值。</li><li>( \\text{EW}_{(1)} )：组内“最早达标孕周”排序后第 1 位的数值（即最小值）。</li><li>( \\text{EW}_{(n_g)} )：组内“最早达标孕周”排序后第 ( n_g ) 位的数值（即最大值）。</li><li>( n_g )：BMI 组 ( g ) 内的样本量。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\min</span>_g = <span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_<span class="token punctuation">{</span>(1)<span class="token punctuation">}</span>, <span class="token function selector">\\quad</span> <span class="token function selector">\\max</span>_g = <span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_<span class="token punctuation">{</span>(n_g)<span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式5-p-分位数-q-p-g" tabindex="-1"><a class="header-anchor" href="#公式5-p-分位数-q-p-g"><span>公式5：( p )-分位数 ( Q_p(g) )</span></a></h4><ul><li><strong>公式内容</strong>：( p )-分位数（经验分位）( Q_p(g) = \\text{EW}_{\\left( \\lceil p \\cdot n_g \\rceil \\right)} )（( p = 0.90, 0.95 )）。</li><li><strong>变量说明</strong>： <ul><li>( Q_p(g) )：BMI 组 ( g ) 内“最早达标孕周”的 ( p )-分位数。</li><li>( p )：分位数的比例，这里取 ( 0.90 ) 和 ( 0.95 )。</li><li>( \\text{EW}_{\\left( \\lceil p \\cdot n_g \\rceil \\right)} )：将组内“最早达标孕周”排序后，位于第 ( \\lceil p \\cdot n_g \\rceil ) 位的数值。</li><li>( n_g )：BMI 组 ( g ) 内的样本量。</li><li>( \\lceil \\cdot \\rceil )：向上取整函数。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">Q_p(g) = <span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\left</span>( <span class="token function selector">\\lceil</span> p <span class="token function selector">\\cdot</span> n_g <span class="token function selector">\\rceil</span> <span class="token function selector">\\right</span>)<span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><p>（( p = 0.90, 0.95 ) 可表示为 ( p \\in { 0.90, 0.95 } )，LaTeX 为 ( p = 0.90,\\ 0.95 )）</p><h4 id="公式6-建议首检时点-t-g-1-和建议复检时点-t-g-2" tabindex="-1"><a class="header-anchor" href="#公式6-建议首检时点-t-g-1-和建议复检时点-t-g-2"><span>公式6：建议首检时点 ( T_g^{(1)} ) 和建议复检时点 ( T_g^{(2)} )</span></a></h4><ul><li><strong>公式内容</strong>：建议首检时点 ( T_g^{(1)} = Q_{0.90}(g) )，建议复检时点 ( T_g^{(2)} = Q_{0.95}(g) )。</li><li><strong>变量说明</strong>： <ul><li>( T_g^{(1)} )：BMI 组 ( g ) 对应的建议首检时点。</li><li>( T_g^{(2)} )：BMI 组 ( g ) 对应的建议复检时点。</li><li>( Q_{0.90}(g) )：BMI 组 ( g ) 内“最早达标孕周”的 ( 0.90 )-分位数。</li><li>( Q_{0.95}(g) )：BMI 组 ( g ) 内“最早达标孕周”的 ( 0.95 )-分位数。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">T_g^<span class="token punctuation">{</span>(1)<span class="token punctuation">}</span> = Q_<span class="token punctuation">{</span>0.90<span class="token punctuation">}</span>(g)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">T_g^<span class="token punctuation">{</span>(2)<span class="token punctuation">}</span> = Q_<span class="token punctuation">{</span>0.95<span class="token punctuation">}</span>(g)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h1 id="第三题" tabindex="-1"><a class="header-anchor" href="#第三题"><span>第三题</span></a></h1><hr><h3 id="数据预处理相关" tabindex="-1"><a class="header-anchor" href="#数据预处理相关"><span>数据预处理相关</span></a></h3><h4 id="公式1-孕周统一-周-天转换" tabindex="-1"><a class="header-anchor" href="#公式1-孕周统一-周-天转换"><span>公式1：孕周统一（周 + 天转换）</span></a></h4><ul><li><strong>公式内容</strong>：若原始孕周为“周 + 天”，记为 ( GA = w + \\frac{d}{7} )；若为小数，直接取值；仅保留合理时窗 ([10, 25])。</li><li><strong>变量说明</strong>： <ul><li>( GA )：统一后的孕周。</li><li>( w )：原始孕周的“周”部分。</li><li>( d )：原始孕周的“天”部分。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">GA = w + <span class="token function selector">\\frac</span><span class="token punctuation">{</span>d<span class="token punctuation">}</span><span class="token punctuation">{</span>7<span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式2-同孕周汇总-取最大值" tabindex="-1"><a class="header-anchor" href="#公式2-同孕周汇总-取最大值"><span>公式2：同孕周汇总（取最大值）</span></a></h4><ul><li><strong>公式内容</strong>：对同一孕妇、同一孕周的多次检测，取 ( Y^{\\max}(g) = \\max Y )。</li><li><strong>变量说明</strong>： <ul><li>( Y^{\\max}(g) )：同一孕妇、孕周 ( g ) 下检测指标的最大值。</li><li>( Y )：该孕妇、孕周 ( g ) 下的检测指标值。</li><li>( g )：孕周。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">Y^<span class="token punctuation">{</span><span class="token function selector">\\max</span><span class="token punctuation">}</span>(g) = <span class="token function selector">\\max</span> Y</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式3-事件时间-监督信号" tabindex="-1"><a class="header-anchor" href="#公式3-事件时间-监督信号"><span>公式3：事件时间（监督信号）</span></a></h4><ul><li><strong>公式内容</strong>：( \\text{EW} = \\min{ g: Y^{\\max}(g) \\geq \\tau } )（( \\tau = 4% )）。</li><li><strong>变量说明</strong>： <ul><li>( \\text{EW} )：事件时间（最早达标孕周）。</li><li>( g )：孕周。</li><li>( Y^{\\max}(g) )：同一孕妇、孕周 ( g ) 下检测指标的最大值。</li><li>( \\tau )：阈值，这里为 ( 4% )。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span> = <span class="token function selector">\\min</span><span class="token function selector">\\{</span> g: Y^<span class="token punctuation">{</span><span class="token function selector">\\max</span><span class="token punctuation">}</span>(g) <span class="token function selector">\\geq</span> <span class="token function selector">\\tau</span> <span class="token function selector">\\}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式4-bmi-分箱-cart-最优阈值" tabindex="-1"><a class="header-anchor" href="#公式4-bmi-分箱-cart-最优阈值"><span>公式4：BMI 分箱（CART 最优阈值）</span></a></h4><ul><li><strong>公式内容</strong>：内部结点阈值 ( c^* ) 由最小化组内平方误差和得到，( c^* \\in \\arg\\min_{c} \\sum_{x &lt; c} (\\text{EW} - \\overline{\\text{EW}}<em>L)^2 + \\sum</em>{x \\geq c} (\\text{EW} - \\overline{\\text{EW}}_R)^2 )。</li><li><strong>变量说明</strong>： <ul><li>( c^* )：最优的内部结点阈值。</li><li>( \\arg\\min_{c} )：使后面表达式取得最小值的 ( c ) 的集合。</li><li>( \\text{EW} )：事件时间（最早达标孕周）。</li><li>( \\overline{\\text{EW}}_L )：阈值 ( c ) 左侧样本的 ( \\text{EW} ) 均值。</li><li>( \\overline{\\text{EW}}_R )：阈值 ( c ) 右侧样本的 ( \\text{EW} ) 均值。</li><li>( x )：样本的 BMI 等特征值。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">c^* <span class="token function selector">\\in</span> <span class="token function selector">\\arg</span><span class="token function selector">\\min</span>_<span class="token punctuation">{</span>c<span class="token punctuation">}</span> <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>x &lt; c<span class="token punctuation">}</span> (<span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span> - <span class="token function selector">\\overline</span><span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span><span class="token punctuation">}</span>_L)^2 + <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>x <span class="token function selector">\\geq</span> c<span class="token punctuation">}</span> (<span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span> - <span class="token function selector">\\overline</span><span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>EW<span class="token punctuation">}</span><span class="token punctuation">}</span>_R)^2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式5-区间中点-人-区间构造" tabindex="-1"><a class="header-anchor" href="#公式5-区间中点-人-区间构造"><span>公式5：区间中点（人 - 区间构造）</span></a></h4><ul><li><strong>公式内容</strong>：区间特征含 ( \\text{interval_mid} = \\frac{t_k + t_{k+1}}{2} )。</li><li><strong>变量说明</strong>： <ul><li>( \\text{interval_mid} )：相邻孕周点 ( [t_k, t_{k+1}) ) 区间的中点。</li><li>( t_k )、( t_{k+1} )：相邻的孕周点。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>interval<span class="token function selector">\\_</span>mid<span class="token punctuation">}</span> = <span class="token function selector">\\frac</span><span class="token punctuation">{</span>t_k + t_<span class="token punctuation">{</span>k+1<span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">{</span>2<span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="生存森林相关" tabindex="-1"><a class="header-anchor" href="#生存森林相关"><span>生存森林相关</span></a></h3><h4 id="公式1-区间危险度-hat-h-i-t" tabindex="-1"><a class="header-anchor" href="#公式1-区间危险度-hat-h-i-t"><span>公式1：区间危险度 ( \\hat{h}_i(t) )</span></a></h4><ul><li><strong>公式内容</strong>：用随机森林分类器估计区间危险度 ( \\hat{h}_i(t) = \\Pr(\\text{event} = 1 \\mid \\text{features at } t) )，并用等距网格 ( t = 10, 10.2, \\dots, 25 ) 逐点预测。</li><li><strong>变量说明</strong>： <ul><li>( \\hat{h}_i(t) )：第 ( i ) 个样本在孕周 ( t ) 时的区间危险度估计值。</li><li>( \\Pr(\\text{event} = 1 \\mid \\text{features at } t) )：在孕周 ( t ) 时特征下，事件（首次达标发生在右端点）发生的概率。</li><li>( t )：孕周，取值为等距网格 ( 10, 10.2, \\dots, 25 )。</li><li>( i )：样本索引。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\hat</span><span class="token punctuation">{</span>h<span class="token punctuation">}</span>_i(t) = <span class="token function selector">\\Pr</span>(<span class="token function selector">\\text</span><span class="token punctuation">{</span>event<span class="token punctuation">}</span> = 1 <span class="token function selector">\\mid</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>features at <span class="token punctuation">}</span> t)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式2-递推个体生存-hat-s-i-t-和累计达标-hat-f-i-t" tabindex="-1"><a class="header-anchor" href="#公式2-递推个体生存-hat-s-i-t-和累计达标-hat-f-i-t"><span>公式2：递推个体生存 ( \\hat{S}_i(t) ) 和累计达标 ( \\hat{F}_i(t) )</span></a></h4><ul><li><strong>公式内容</strong>：( \\hat{S}<em>i(t) = \\prod</em>{u \\leq t} (1 - \\hat{h}_i(u)) )，( \\hat{F}_i(t) = 1 - \\hat{S}_i(t) )。</li><li><strong>变量说明</strong>： <ul><li>( \\hat{S}_i(t) )：第 ( i ) 个样本在孕周 ( t ) 时的生存函数估计值（未达标概率）。</li><li>( \\hat{F}_i(t) )：第 ( i ) 个样本在孕周 ( t ) 时的累计达标函数估计值（达标概率）。</li><li>( \\hat{h}_i(u) )：第 ( i ) 个样本在孕周 ( u ) 时的区间危险度估计值。</li><li>( u )：孕周，( u \\leq t )。</li><li>( t )：孕周。</li><li>( i )：样本索引。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\hat</span><span class="token punctuation">{</span>S<span class="token punctuation">}</span>_i(t) = <span class="token function selector">\\prod</span>_<span class="token punctuation">{</span>u <span class="token function selector">\\leq</span> t<span class="token punctuation">}</span> (1 - <span class="token function selector">\\hat</span><span class="token punctuation">{</span>h<span class="token punctuation">}</span>_i(u))</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\hat</span><span class="token punctuation">{</span>F<span class="token punctuation">}</span>_i(t) = 1 - <span class="token function selector">\\hat</span><span class="token punctuation">{</span>S<span class="token punctuation">}</span>_i(t)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="公式3-组内平均-hat-f-text-group-t" tabindex="-1"><a class="header-anchor" href="#公式3-组内平均-hat-f-text-group-t"><span>公式3：组内平均 ( \\hat{F}_{\\text{group}}(t) )</span></a></h4><ul><li><strong>公式内容</strong>：( \\hat{F}<em>{\\text{group}}(t) = \\frac{1}{|G|} \\sum</em>{i \\in G} \\hat{F}_i(t) )。</li><li><strong>变量说明</strong>： <ul><li>( \\hat{F}_{\\text{group}}(t) )：某一组在孕周 ( t ) 时的累计达标函数组内平均值。</li><li>( |G| )：组 ( G ) 内样本的数量。</li><li>( \\hat{F}_i(t) )：组 ( G ) 内第 ( i ) 个样本在孕周 ( t ) 时的累计达标函数估计值。</li><li>( i )：样本索引，( i \\in G ) 表示样本 ( i ) 属于组 ( G )。</li><li>( t )：孕周。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\hat</span><span class="token punctuation">{</span>F<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>group<span class="token punctuation">}</span><span class="token punctuation">}</span>(t) = <span class="token function selector">\\frac</span><span class="token punctuation">{</span>1<span class="token punctuation">}</span><span class="token punctuation">{</span>|G|<span class="token punctuation">}</span> <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>i <span class="token function selector">\\in</span> G<span class="token punctuation">}</span> <span class="token function selector">\\hat</span><span class="token punctuation">{</span>F<span class="token punctuation">}</span>_i(t)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="机会约束优化相关" tabindex="-1"><a class="header-anchor" href="#机会约束优化相关"><span>机会约束优化相关</span></a></h3><h4 id="公式-最早满足目标的孕周-t-p" tabindex="-1"><a class="header-anchor" href="#公式-最早满足目标的孕周-t-p"><span>公式：最早满足目标的孕周 ( t^*(p) )</span></a></h4><ul><li><strong>公式内容</strong>：对给定目标 ( p \\in { 0.90, 0.95 } )，求最早满足的孕周 ( t^*(p) = \\min{ t \\in [10, 25] : \\hat{F}_{\\text{group}}(t) \\geq p } )。</li><li><strong>变量说明</strong>： <ul><li>( t^*(p) )：满足累计达标概率至少为 ( p ) 的最早孕周。</li><li>( p )：目标累计达标概率，取 ( 0.90 ) 或 ( 0.95 )。</li><li>( \\hat{F}_{\\text{group}}(t) )：某一组在孕周 ( t ) 时的累计达标函数组内平均值。</li><li>( t )：孕周，范围为 ( [10, 25] )。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">t^*(p) = <span class="token function selector">\\min</span><span class="token function selector">\\{</span> t <span class="token function selector">\\in</span> <span class="token punctuation">[</span>10, 25<span class="token punctuation">]</span> : <span class="token function selector">\\hat</span><span class="token punctuation">{</span>F<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>group<span class="token punctuation">}</span><span class="token punctuation">}</span>(t) <span class="token function selector">\\geq</span> p <span class="token function selector">\\}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h1 id="第四题" tabindex="-1"><a class="header-anchor" href="#第四题"><span>第四题</span></a></h1><hr><h3 id="s2-质控门-qc-gate-相关" tabindex="-1"><a class="header-anchor" href="#s2-质控门-qc-gate-相关"><span>S2 质控门（QC gate）相关</span></a></h3><h4 id="_2-1-孕周窗口约束" tabindex="-1"><a class="header-anchor" href="#_2-1-孕周窗口约束"><span>（2.1）孕周窗口约束</span></a></h4><ul><li><strong>公式内容</strong>：( \\mathbb{I}_{\\text{week}}(i) = \\mathbb{I}{ 10 \\leq GA_i \\leq 25 } )</li><li><strong>变量说明</strong>： <ul><li>( \\mathbb{I}_{\\text{week}}(i) )：指示函数，当样本 ( i ) 的孕周 ( GA_i ) 在 ([10, 25]) 范围内时，值为 ( 1 )，否则为 ( 0 )。</li><li>( GA_i )：样本 ( i ) 的孕周。</li><li>( \\mathbb{I}{\\cdot} )：示性函数，括号内条件满足时取 ( 1 )，不满足时取 ( 0 )。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>week<span class="token punctuation">}</span><span class="token punctuation">}</span>(i) = <span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span><span class="token function selector">\\{</span> 10 <span class="token function selector">\\leq</span> GA_i <span class="token function selector">\\leq</span> 25 <span class="token function selector">\\}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_2-2-质量稳健带-分位裁剪" tabindex="-1"><a class="header-anchor" href="#_2-2-质量稳健带-分位裁剪"><span>（2.2）质量稳健带（分位裁剪）</span></a></h4><ul><li><strong>公式内容</strong>：( \\mathbb{I}<em>{\\text{qc}}(i) = \\prod</em>{m \\in \\mathcal{M}} \\mathbb{I}\\left{ q_L^{(m)} \\leq x_i^{(m)} \\leq q_U^{(m)} \\right} )</li><li><strong>变量说明</strong>： <ul><li>( \\mathbb{I}_{\\text{qc}}(i) )：指示函数，当样本 ( i ) 的所有特征 ( x_i^{(m)} )（( m \\in \\mathcal{M} )）都在对应分位区间 ([q_L^{(m)}, q_U^{(m)}]) 内时，值为 ( 1 )，否则为 ( 0 )。</li><li>( \\mathcal{M} )：特征的索引集合。</li><li>( x_i^{(m)} )：样本 ( i ) 的第 ( m ) 个特征。</li><li>( q_L^{(m)} )：第 ( m ) 个特征的下分位数。</li><li>( q_U^{(m)} )：第 ( m ) 个特征的上分位数。</li><li>( \\mathbb{I}{\\cdot} )：示性函数。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>qc<span class="token punctuation">}</span><span class="token punctuation">}</span>(i) = <span class="token function selector">\\prod</span>_<span class="token punctuation">{</span>m <span class="token function selector">\\in</span> <span class="token function selector">\\mathcal</span><span class="token punctuation">{</span>M<span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span><span class="token function selector">\\left</span><span class="token function selector">\\{</span> q_L^<span class="token punctuation">{</span>(m)<span class="token punctuation">}</span> <span class="token function selector">\\leq</span> x_i^<span class="token punctuation">{</span>(m)<span class="token punctuation">}</span> <span class="token function selector">\\leq</span> q_U^<span class="token punctuation">{</span>(m)<span class="token punctuation">}</span> <span class="token function selector">\\right</span><span class="token function selector">\\}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_2-3-质控门通过指示" tabindex="-1"><a class="header-anchor" href="#_2-3-质控门通过指示"><span>（2.3）质控门通过指示</span></a></h4><ul><li><strong>公式内容</strong>：( \\mathbb{I}<em>{\\text{pass}}(i) = \\mathbb{I}</em>{\\text{week}}(i) \\cdot \\mathbb{I}_{\\text{qc}}(i) )</li><li><strong>变量说明</strong>： <ul><li>( \\mathbb{I}_{\\text{pass}}(i) )：指示函数，当样本 ( i ) 同时满足孕周窗口约束和质量稳健带约束时，值为 ( 1 )（即通过质控门），否则为 ( 0 )。</li><li>( \\mathbb{I}_{\\text{week}}(i) )：孕周窗口约束的指示函数。</li><li>( \\mathbb{I}_{\\text{qc}}(i) )：质量稳健带约束的指示函数。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>pass<span class="token punctuation">}</span><span class="token punctuation">}</span>(i) = <span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>week<span class="token punctuation">}</span><span class="token punctuation">}</span>(i) <span class="token function selector">\\cdot</span> <span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>qc<span class="token punctuation">}</span><span class="token punctuation">}</span>(i)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="s3-特征装配与缺失填补相关" tabindex="-1"><a class="header-anchor" href="#s3-特征装配与缺失填补相关"><span>S3 特征装配与缺失填补相关</span></a></h3><h4 id="_3-1-数值化与中位数填补" tabindex="-1"><a class="header-anchor" href="#_3-1-数值化与中位数填补"><span>（3.1）数值化与中位数填补</span></a></h4><ul><li><strong>公式内容</strong>：( \\tilde{x}<em>{ij} = \\begin{cases} x</em>{ij}, &amp; x_{ij} \\text{ 非缺失} \\ \\text{median}{ x_{\\ell j}: \\mathbb{I}_{\\text{pass}}(\\ell) = 1 }, &amp; \\text{否则} \\end{cases} )</li><li><strong>变量说明</strong>： <ul><li>( \\tilde{x}_{ij} )：填补后样本 ( i ) 的第 ( j ) 个特征值。</li><li>( x_{ij} )：样本 ( i ) 第 ( j ) 个特征的原始值。</li><li>( \\text{median}{\\cdot} )：取中位数函数，这里取通过质控门（( \\mathbb{I}_{\\text{pass}}(\\ell) = 1 )）的样本 ( \\ell ) 第 ( j ) 个特征的中位数。</li><li>( \\ell )：样本索引。</li><li>( \\mathbb{I}_{\\text{pass}}(\\ell) )：样本 ( \\ell ) 质控门通过的指示函数。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\tilde</span><span class="token punctuation">{</span>x<span class="token punctuation">}</span>_<span class="token punctuation">{</span>ij<span class="token punctuation">}</span> = <span class="token function selector">\\begin</span><span class="token punctuation">{</span><span class="token keyword">cases</span><span class="token punctuation">}</span> x_<span class="token punctuation">{</span>ij<span class="token punctuation">}</span>, <span class="token punctuation">&amp;</span> x_<span class="token punctuation">{</span>ij<span class="token punctuation">}</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span> 非缺失<span class="token punctuation">}</span> <span class="token function selector">\\\\</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>median<span class="token punctuation">}</span><span class="token function selector">\\{</span> x_<span class="token punctuation">{</span><span class="token function selector">\\ell</span> j<span class="token punctuation">}</span>: <span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>pass<span class="token punctuation">}</span><span class="token punctuation">}</span>(<span class="token function selector">\\ell</span>) = 1 <span class="token function selector">\\}</span>, <span class="token punctuation">&amp;</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>否则<span class="token punctuation">}</span> <span class="token function selector">\\end</span><span class="token punctuation">{</span><span class="token keyword">cases</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="s4-成本敏感-lightgbm-概率模型-相关" tabindex="-1"><a class="header-anchor" href="#s4-成本敏感-lightgbm-概率模型-相关"><span>S4 成本敏感 LightGBM（概率模型）相关</span></a></h3><h4 id="_4-1-逻辑概率映射" tabindex="-1"><a class="header-anchor" href="#_4-1-逻辑概率映射"><span>（4.1）逻辑概率映射</span></a></h4><ul><li><strong>公式内容</strong>：( \\hat{p}<em>{\\theta}(x) = \\sigma(f</em>{\\theta}(x)) = \\frac{1}{1 + e^{-f_{\\theta}(x)}} )</li><li><strong>变量说明</strong>： <ul><li>( \\hat{p}_{\\theta}(x) )：模型对样本 ( x ) 的预测概率。</li><li>( \\sigma(\\cdot) )：Sigmoid 函数，用于将模型输出 ( f_{\\theta}(x) ) 映射到 ((0, 1)) 区间，代表概率。</li><li>( f_{\\theta}(x) )：LightGBM 模型的输出（未经过 Sigmoid 变换）。</li><li>( \\theta )：模型参数。</li><li>( x )：输入样本。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span>(x) = <span class="token function selector">\\sigma</span>(f_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span>(x)) = <span class="token function selector">\\frac</span><span class="token punctuation">{</span>1<span class="token punctuation">}</span><span class="token punctuation">{</span>1 + e^<span class="token punctuation">{</span>-f_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span>(x)<span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="s4-成本敏感-lightgbm-概率模型-相关-1" tabindex="-1"><a class="header-anchor" href="#s4-成本敏感-lightgbm-概率模型-相关-1"><span>S4 成本敏感 LightGBM（概率模型）相关</span></a></h3><h4 id="_4-1-逻辑概率映射-1" tabindex="-1"><a class="header-anchor" href="#_4-1-逻辑概率映射-1"><span>（4.1）逻辑概率映射</span></a></h4><ul><li><strong>公式内容</strong>：( \\hat{p}<em>{\\theta}(x) = \\sigma(f</em>{\\theta}(x)) = \\frac{1}{1 + e^{-f_{\\theta}(x)}} )</li><li><strong>变量说明</strong>： <ul><li>( \\hat{p}_{\\theta}(x) )：模型对样本 ( x ) 的预测异常概率。</li><li>( \\sigma(\\cdot) )：Sigmoid 函数，将梯度提升树的加性打分 ( f_{\\theta}(x) ) 映射到 ((0, 1)) 区间表示概率。</li><li>( f_{\\theta}(x) )：LightGBM 模型的加性输出打分。</li><li>( \\theta )：模型参数。</li><li>( x )：输入样本。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span>(x) = <span class="token function selector">\\sigma</span>(f_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span>(x)) = <span class="token function selector">\\frac</span><span class="token punctuation">{</span>1<span class="token punctuation">}</span><span class="token punctuation">{</span>1 + e^<span class="token punctuation">{</span>-f_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span>(x)<span class="token punctuation">}</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_4-2-类别权重-阳性稀缺" tabindex="-1"><a class="header-anchor" href="#_4-2-类别权重-阳性稀缺"><span>（4.2）类别权重（阳性稀缺）</span></a></h4><ul><li><strong>公式内容</strong>：( w_1 = \\frac{N_0}{\\max(1, N_1)}, \\quad w_0 = 1 )</li><li><strong>变量说明</strong>： <ul><li>( w_1 )：阳性类别（类别 ( 1 )）的权重。</li><li>( w_0 )：阴性类别（类别 ( 0 )）的权重（固定为 ( 1 )）。</li><li>( N_0 )：阴性类别（类别 ( 0 )）的训练样本数。</li><li>( N_1 )：阳性类别（类别 ( 1 )）的训练样本数。</li><li>( \\max(1, N_1) )：取 ( 1 ) 和 ( N_1 ) 中的较大值，避免分母过小。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">w_1 = <span class="token function selector">\\frac</span><span class="token punctuation">{</span>N_0<span class="token punctuation">}</span><span class="token punctuation">{</span><span class="token function selector">\\max</span>(1, N_1)<span class="token punctuation">}</span>, <span class="token function selector">\\quad</span> w_0 = 1</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_4-3-加权交叉熵目标-带正则" tabindex="-1"><a class="header-anchor" href="#_4-3-加权交叉熵目标-带正则"><span>（4.3）加权交叉熵目标（带正则）</span></a></h4><ul><li><strong>公式内容</strong>：( \\min_{\\theta} \\sum_{(x_i, y_i) \\in \\mathcal{D}<em>{\\text{tr}}} w</em>{y_i} \\left[ - y_i \\log \\hat{p}<em>{\\theta}(x_i) - (1 - y_i) \\log \\left( 1 - \\hat{p}</em>{\\theta}(x_i) \\right) \\right] + \\lambda |\\theta|_2^2 )</li><li><strong>变量说明</strong>： <ul><li>( \\theta )：模型参数，需最小化目标函数来学习。</li><li>( \\mathcal{D}_{\\text{tr}} )：训练数据集。</li><li>( (x_i, y_i) )：训练集中的样本（特征 ( x_i )，标签 ( y_i )）。</li><li>( w_{y_i} )：根据样本标签 ( y_i ) 确定的类别权重（( y_i = 1 ) 时为 ( w_1 )，( y_i = 0 ) 时为 ( w_0 )）。</li><li>( \\hat{p}_{\\theta}(x_i) )：模型对样本 ( x_i ) 的预测概率。</li><li>( \\lambda )：正则化系数，控制模型复杂度，避免过拟合。</li><li>( |\\theta|_2^2 )：模型参数 ( \\theta ) 的 ( L_2 ) 范数的平方，起正则化作用。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\min</span>_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span> <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>(x_i, y_i) <span class="token function selector">\\in</span> <span class="token function selector">\\mathcal</span><span class="token punctuation">{</span>D<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>tr<span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">}</span> w_<span class="token punctuation">{</span>y_i<span class="token punctuation">}</span> <span class="token function selector">\\left</span><span class="token punctuation">[</span> - y_i <span class="token function selector">\\log</span> <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span>(x_i) - (1 - y_i) <span class="token function selector">\\log</span> <span class="token function selector">\\left</span>( 1 - <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\theta</span><span class="token punctuation">}</span>(x_i) <span class="token function selector">\\right</span>) <span class="token function selector">\\right</span><span class="token punctuation">]</span> + <span class="token function selector">\\lambda</span> <span class="token function selector">\\|</span><span class="token function selector">\\theta</span><span class="token function selector">\\|</span>_2^2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="s5-概率校准-等温回归-isotonic-相关" tabindex="-1"><a class="header-anchor" href="#s5-概率校准-等温回归-isotonic-相关"><span>S5 概率校准（等温回归 Isotonic）相关</span></a></h3><h4 id="_5-1-单调校准映射" tabindex="-1"><a class="header-anchor" href="#_5-1-单调校准映射"><span>（5.1）单调校准映射</span></a></h4><ul><li><strong>公式内容</strong>：( \\hat{p}(x) = g(\\hat{p}<em>{\\text{raw}}(x)), \\quad g = \\arg\\min</em>{g \\text{ 单调非降}} \\sum_{(x_i, y_i) \\in \\mathcal{D}<em>{\\text{cal}}} \\left( g(\\hat{p}</em>{\\text{raw}}(x_i)) - y_i \\right)^2 )</li><li><strong>变量说明</strong>： <ul><li>( \\hat{p}(x) )：校准后样本 ( x ) 的预测概率。</li><li>( g(\\cdot) )：单调非降的校准映射函数，通过最小化校准数据集上的平方误差学习得到。</li><li>( \\hat{p}_{\\text{raw}}(x) )：模型原始的未校准预测概率。</li><li>( \\arg\\min_{g \\text{ 单调非降}} )：寻找满足“单调非降”约束的函数 ( g )，使后面的平方误差和最小。</li><li>( \\mathcal{D}_{\\text{cal}} )：校准数据集。</li><li>( (x_i, y_i) )：校准集中的样本（特征 ( x_i )，标签 ( y_i )）。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>(x) = g(<span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>raw<span class="token punctuation">}</span><span class="token punctuation">}</span>(x)), <span class="token function selector">\\quad</span> g = <span class="token function selector">\\arg</span><span class="token function selector">\\min</span>_<span class="token punctuation">{</span>g <span class="token function selector">\\text</span><span class="token punctuation">{</span> 单调非降<span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>(x_i, y_i) <span class="token function selector">\\in</span> <span class="token function selector">\\mathcal</span><span class="token punctuation">{</span>D<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>cal<span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token function selector">\\left</span>( g(<span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>raw<span class="token punctuation">}</span><span class="token punctuation">}</span>(x_i)) - y_i <span class="token function selector">\\right</span>)^2</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="s6-分割式-conformal-选择性-拒判相关" tabindex="-1"><a class="header-anchor" href="#s6-分割式-conformal-选择性-拒判相关"><span>S6 分割式 Conformal 选择性/拒判相关</span></a></h3><h4 id="_6-1-校准集非一致性分数-二分类" tabindex="-1"><a class="header-anchor" href="#_6-1-校准集非一致性分数-二分类"><span>（6.1）校准集非一致性分数（二分类）</span></a></h4><ul><li><strong>公式内容</strong>：( s_i = 1 - \\left[ y_i \\hat{p}_i + (1 - y_i)(1 - \\hat{p}_i) \\right] = \\min{\\hat{p}_i, 1 - \\hat{p}_i} )（其中 ( \\hat{p}_i = \\hat{p}(x_i) )）</li><li><strong>变量说明</strong>： <ul><li>( s_i )：校准集样本 ( i ) 的非一致性分数。</li><li>( y_i )：校准集样本 ( i ) 的真实标签（二分类，取值 ( 0 ) 或 ( 1 )）。</li><li>( \\hat{p}_i )：模型对校准集样本 ( i ) 的预测概率，( \\hat{p}(x_i) ) 表示模型对样本 ( x_i ) 的预测概率。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">s_i = 1 - <span class="token function selector">\\left</span><span class="token punctuation">[</span> y_i <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_i + (1 - y_i)(1 - <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_i) <span class="token function selector">\\right</span><span class="token punctuation">]</span> = <span class="token function selector">\\min</span><span class="token function selector">\\{</span><span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_i, 1 - <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>_i<span class="token function selector">\\}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_6-2-higher-分位阈值-有限样本保覆盖" tabindex="-1"><a class="header-anchor" href="#_6-2-higher-分位阈值-有限样本保覆盖"><span>（6.2）“higher”分位阈值（有限样本保覆盖）</span></a></h4><ul><li><strong>公式内容</strong>：( q_{\\alpha} = Q_{1 - \\alpha}^{\\text{higher}}({ s_i }<em>{\\mathcal{D}</em>{\\text{cal}}}) )</li><li><strong>变量说明</strong>： <ul><li>( q_{\\alpha} )：“higher”分位阈值，用于后续预测集的确定。</li><li>( Q_{1 - \\alpha}^{\\text{higher}}(\\cdot) )：取集合中第 ( (1 - \\alpha) ) 分位的“higher”分位数函数。</li><li>( { s_i }<em>{\\mathcal{D}</em>{\\text{cal}}} )：校准集 ( \\mathcal{D}_{\\text{cal}} ) 中所有样本的非一致性分数集合。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">q_<span class="token punctuation">{</span><span class="token function selector">\\alpha</span><span class="token punctuation">}</span> = Q_<span class="token punctuation">{</span>1 - <span class="token function selector">\\alpha</span><span class="token punctuation">}</span>^<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>higher<span class="token punctuation">}</span><span class="token punctuation">}</span>(<span class="token function selector">\\{</span> s_i <span class="token function selector">\\}</span>_<span class="token punctuation">{</span><span class="token function selector">\\mathcal</span><span class="token punctuation">{</span>D<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>cal<span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">}</span>)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_6-3-候选标签的非一致性" tabindex="-1"><a class="header-anchor" href="#_6-3-候选标签的非一致性"><span>（6.3）候选标签的非一致性</span></a></h4><ul><li><strong>公式内容</strong>：( s_1(x) = 1 - \\hat{p}(x), \\quad s_0(x) = \\hat{p}(x) )</li><li><strong>变量说明</strong>： <ul><li>( s_1(x) )：候选标签为 ( 1 ) 时的非一致性分数。</li><li>( s_0(x) )：候选标签为 ( 0 ) 时的非一致性分数。</li><li>( \\hat{p}(x) )：模型对样本 ( x ) 的预测概率。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">s_1(x) = 1 - <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>(x), <span class="token function selector">\\quad</span> s_0(x) = <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>(x)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_6-4-预测集与决策-预测集" tabindex="-1"><a class="header-anchor" href="#_6-4-预测集与决策-预测集"><span>（6.4）预测集与决策（预测集）</span></a></h4><ul><li><strong>公式内容</strong>：( S(x) = { y \\in {0, 1} : s_y(x) \\leq q_{\\alpha} } )</li><li><strong>变量说明</strong>： <ul><li>( S(x) )：样本 ( x ) 的预测集，包含满足非一致性分数不超过阈值 ( q_{\\alpha} ) 的候选标签。</li><li>( y )：候选标签（取值 ( 0 ) 或 ( 1 )）。</li><li>( s_y(x) )：候选标签 ( y ) 对应的非一致性分数。</li><li>( q_{\\alpha} )：“higher”分位阈值。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">S(x) = <span class="token function selector">\\{</span> y <span class="token function selector">\\in</span> <span class="token function selector">\\{</span>0, 1<span class="token function selector">\\}</span> : s_y(x) <span class="token function selector">\\leq</span> q_<span class="token punctuation">{</span><span class="token function selector">\\alpha</span><span class="token punctuation">}</span> <span class="token function selector">\\}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_6-5-预测集与决策-决策规则" tabindex="-1"><a class="header-anchor" href="#_6-5-预测集与决策-决策规则"><span>（6.5）预测集与决策（决策规则）</span></a></h4><ul><li><strong>公式内容</strong>：( |S(x)| = \\begin{cases} 1, &amp; \\text{接受（直接出报告）} \\ 0 \\text{ 或 } 2, &amp; \\text{拒判（建议复检）} \\end{cases} )</li><li><strong>变量说明</strong>： <ul><li>( |S(x)| )：预测集 ( S(x) ) 的大小（元素个数）。</li><li>“接受（直接出报告）”：当预测集大小为 ( 1 ) 时，给出确定类别，直接出报告。</li><li>“拒判（建议复检）”：当预测集大小为 ( 0 ) 或 ( 2 ) 时，拒绝判定，建议复检。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line">|S(x)| = <span class="token function selector">\\begin</span><span class="token punctuation">{</span><span class="token keyword">cases</span><span class="token punctuation">}</span> 1, <span class="token punctuation">&amp;</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>接受（直接出报告）<span class="token punctuation">}</span> <span class="token function selector">\\\\</span> 0 <span class="token function selector">\\text</span><span class="token punctuation">{</span> 或 <span class="token punctuation">}</span> 2, <span class="token punctuation">&amp;</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>拒判（建议复检）<span class="token punctuation">}</span> <span class="token function selector">\\end</span><span class="token punctuation">{</span><span class="token keyword">cases</span><span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="s7-选择性评价与风险-覆盖曲线相关" tabindex="-1"><a class="header-anchor" href="#s7-选择性评价与风险-覆盖曲线相关"><span>S7 选择性评价与风险 - 覆盖曲线相关</span></a></h3><h4 id="_7-1-选择性覆盖率-接受比例" tabindex="-1"><a class="header-anchor" href="#_7-1-选择性覆盖率-接受比例"><span>（7.1）选择性覆盖率（接受比例）</span></a></h4><ul><li><strong>公式内容</strong>：( \\text{Coverage} = \\frac{1}{|\\mathcal{D}<em>{\\text{te}}|} \\sum</em>{x \\in \\mathcal{D}_{\\text{te}}} \\mathbb{I}(|S(x)| = 1) )</li><li><strong>变量说明</strong>： <ul><li>( \\text{Coverage} )：选择性覆盖率，即测试集 ( \\mathcal{D}_{\\text{te}} ) 中被“接受（直接出报告）”的样本比例。</li><li>( |\\mathcal{D}<em>{\\text{te}}| )：测试集 ( \\mathcal{D}</em>{\\text{te}} ) 的样本数量。</li><li>( \\mathbb{I}(|S(x)| = 1) )：示性函数，当样本 ( x ) 的预测集大小 ( |S(x)| = 1 ) 时，值为 ( 1 )，否则为 ( 0 )。</li><li>( x )：测试集 ( \\mathcal{D}_{\\text{te}} ) 中的样本。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>Coverage<span class="token punctuation">}</span> = <span class="token function selector">\\frac</span><span class="token punctuation">{</span>1<span class="token punctuation">}</span><span class="token punctuation">{</span>|<span class="token function selector">\\mathcal</span><span class="token punctuation">{</span>D<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>te<span class="token punctuation">}</span><span class="token punctuation">}</span>|<span class="token punctuation">}</span> <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>x <span class="token function selector">\\in</span> <span class="token function selector">\\mathcal</span><span class="token punctuation">{</span>D<span class="token punctuation">}</span>_<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>te<span class="token punctuation">}</span><span class="token punctuation">}</span><span class="token punctuation">}</span> <span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>(|S(x)| = 1)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_7-2-选择性错误率-在被接受样本上" tabindex="-1"><a class="header-anchor" href="#_7-2-选择性错误率-在被接受样本上"><span>（7.2）选择性错误率（在被接受样本上）</span></a></h4><ul><li><strong>公式内容</strong>：( \\text{SelErr} = \\Pr(\\hat{y} \\neq y \\mid |S(x)| = 1) = \\frac{\\sum_{x: |S(x)| = 1} \\mathbb{I}(\\hat{y} \\neq y)}{\\sum_{x} \\mathbb{I}(|S(x)| = 1)} )</li><li><strong>变量说明</strong>： <ul><li>( \\text{SelErr} )：选择性错误率，即在被接受（( |S(x)| = 1 )）的样本上，预测标签 ( \\hat{y} ) 与真实标签 ( y ) 不相等的概率。</li><li>( \\Pr(\\hat{y} \\neq y \\mid |S(x)| = 1) )：条件概率，表示在 ( |S(x)| = 1 ) 的条件下，( \\hat{y} \\neq y ) 的概率。</li><li>( \\hat{y} )：模型对样本 ( x ) 的预测标签。</li><li>( y )：样本 ( x ) 的真实标签。</li><li>( \\mathbb{I}(\\hat{y} \\neq y) )：示性函数，当 ( \\hat{y} \\neq y ) 时，值为 ( 1 )，否则为 ( 0 )。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>SelErr<span class="token punctuation">}</span> = <span class="token function selector">\\Pr</span>(<span class="token function selector">\\hat</span><span class="token punctuation">{</span>y<span class="token punctuation">}</span> <span class="token function selector">\\neq</span> y <span class="token function selector">\\mid</span> |S(x)| = 1) = <span class="token function selector">\\frac</span><span class="token punctuation">{</span><span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>x: |S(x)| = 1<span class="token punctuation">}</span> <span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>(<span class="token function selector">\\hat</span><span class="token punctuation">{</span>y<span class="token punctuation">}</span> <span class="token function selector">\\neq</span> y)<span class="token punctuation">}</span><span class="token punctuation">{</span><span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>x<span class="token punctuation">}</span> <span class="token function selector">\\mathbb</span><span class="token punctuation">{</span>I<span class="token punctuation">}</span>(|S(x)| = 1)<span class="token punctuation">}</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_7-3-auc-阈值无关评估" tabindex="-1"><a class="header-anchor" href="#_7-3-auc-阈值无关评估"><span>（7.3）AUC（阈值无关评估）</span></a></h4><ul><li><strong>公式内容</strong>：( \\text{AUC} = \\Pr\\left( \\hat{p}(x^+) &gt; \\hat{p}(x^-) \\right) )</li><li><strong>变量说明</strong>： <ul><li>( \\text{AUC} )：曲线下面积，衡量模型对正样本（( x^+ )）和负样本（( x^- )）的区分能力，即正样本预测概率大于负样本预测概率的概率。</li><li>( \\hat{p}(x^+) )：模型对正样本 ( x^+ ) 的预测概率。</li><li>( \\hat{p}(x^-) )：模型对负样本 ( x^- ) 的预测概率。</li><li>( \\Pr\\left( \\hat{p}(x^+) &gt; \\hat{p}(x^-) \\right) )：正样本预测概率大于负样本预测概率的概率。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>AUC<span class="token punctuation">}</span> = <span class="token function selector">\\Pr</span><span class="token function selector">\\left</span>( <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>(x^+) &gt; <span class="token function selector">\\hat</span><span class="token punctuation">{</span>p<span class="token punctuation">}</span>(x^-) <span class="token function selector">\\right</span>)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_7-4-ap-阈值无关评估" tabindex="-1"><a class="header-anchor" href="#_7-4-ap-阈值无关评估"><span>（7.4）AP（阈值无关评估）</span></a></h4><ul><li><strong>公式内容</strong>：( \\text{AP} = \\sum_{k} \\text{Prec}@k \\cdot \\Delta \\text{Rec}@k )</li><li><strong>变量说明</strong>： <ul><li>( \\text{AP} )：平均精度，衡量在不同召回率下的平均精度，与拒判阈值解耦。</li><li>( \\text{Prec}@k )：第 ( k ) 个位置的精度（ Precision）。</li><li>( \\Delta \\text{Rec}@k )：第 ( k ) 个位置召回率（ Recall）的增量。</li><li>( k )：排序位置索引。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\text</span><span class="token punctuation">{</span>AP<span class="token punctuation">}</span> = <span class="token function selector">\\sum</span>_<span class="token punctuation">{</span>k<span class="token punctuation">}</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>Prec<span class="token punctuation">}</span>@k <span class="token function selector">\\cdot</span> <span class="token function selector">\\Delta</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>Rec<span class="token punctuation">}</span>@k</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_7-5-风险-覆盖曲线-参数-alpha" tabindex="-1"><a class="header-anchor" href="#_7-5-风险-覆盖曲线-参数-alpha"><span>（7.5）风险 - 覆盖曲线（参数 ( \\alpha )）</span></a></h4><ul><li><strong>公式内容</strong>：( \\left( \\text{Coverage}(\\alpha), \\text{SelErr} \\downarrow \\right), \\quad q_{\\alpha} = Q_{1 - \\alpha}^{\\text{higher}}({ s_i }) )</li><li><strong>变量说明</strong>： <ul><li>( \\text{Coverage}(\\alpha) )：对应参数 ( \\alpha ) 下的选择性覆盖率。</li><li>( \\text{SelErr} \\downarrow )：随着 ( \\alpha ) 等参数变化，选择性错误率下降。</li><li>( q_{\\alpha} = Q_{1 - \\alpha}^{\\text{higher}}({ s_i }) )：“higher”分位阈值，由校准集非一致性分数集合 ( { s_i } ) 确定。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\left</span>( <span class="token function selector">\\text</span><span class="token punctuation">{</span>Coverage<span class="token punctuation">}</span>(<span class="token function selector">\\alpha</span>), <span class="token function selector">\\text</span><span class="token punctuation">{</span>SelErr<span class="token punctuation">}</span> <span class="token function selector">\\downarrow</span> <span class="token function selector">\\right</span>), <span class="token function selector">\\quad</span> q_<span class="token punctuation">{</span><span class="token function selector">\\alpha</span><span class="token punctuation">}</span> = Q_<span class="token punctuation">{</span>1 - <span class="token function selector">\\alpha</span><span class="token punctuation">}</span>^<span class="token punctuation">{</span><span class="token function selector">\\text</span><span class="token punctuation">{</span>higher<span class="token punctuation">}</span><span class="token punctuation">}</span>(<span class="token function selector">\\{</span> s_i <span class="token function selector">\\}</span>)</span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h3 id="s8-工作点选择与-sop-映射相关" tabindex="-1"><a class="header-anchor" href="#s8-工作点选择与-sop-映射相关"><span>S8 工作点选择与 SOP 映射相关</span></a></h3><h4 id="_8-1-以覆盖为硬约束最小化错误" tabindex="-1"><a class="header-anchor" href="#_8-1-以覆盖为硬约束最小化错误"><span>（8.1）以覆盖为硬约束最小化错误</span></a></h4><ul><li><strong>公式内容</strong>：( \\alpha^{\\star} = \\arg\\min_{\\alpha} \\text{SelErr}(\\alpha) \\quad \\text{s.t.} \\ \\text{Coverage}(\\alpha) \\geq \\tau )</li><li><strong>变量说明</strong>： <ul><li>( \\alpha^{\\star} )：最优的参数 ( \\alpha )。</li><li>( \\arg\\min_{\\alpha} )：寻找使 ( \\text{SelErr}(\\alpha) ) 最小的 ( \\alpha )。</li><li>( \\text{SelErr}(\\alpha) )：对应参数 ( \\alpha ) 的选择性错误率。</li><li>( \\text{Coverage}(\\alpha) )：对应参数 ( \\alpha ) 的选择性覆盖率。</li><li>( \\tau )：覆盖阈值，作为硬约束要求覆盖率不低于 ( \\tau )。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\alpha</span>^<span class="token punctuation">{</span><span class="token function selector">\\star</span><span class="token punctuation">}</span> = <span class="token function selector">\\arg</span><span class="token function selector">\\min</span>_<span class="token punctuation">{</span><span class="token function selector">\\alpha</span><span class="token punctuation">}</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>SelErr<span class="token punctuation">}</span>(<span class="token function selector">\\alpha</span>) <span class="token function selector">\\quad</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>s.t.<span class="token punctuation">}</span> <span class="token function selector">\\ </span><span class="token function selector">\\text</span><span class="token punctuation">{</span>Coverage<span class="token punctuation">}</span>(<span class="token function selector">\\alpha</span>) <span class="token function selector">\\geq</span> <span class="token function selector">\\tau</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div><h4 id="_8-2-以错误为硬约束最大化覆盖" tabindex="-1"><a class="header-anchor" href="#_8-2-以错误为硬约束最大化覆盖"><span>（8.2）以错误为硬约束最大化覆盖</span></a></h4><ul><li><strong>公式内容</strong>：( \\alpha^{\\star} = \\arg\\max_{\\alpha} \\text{Coverage}(\\alpha) \\quad \\text{s.t.} \\ \\text{SelErr}(\\alpha) \\leq \\varepsilon )</li><li><strong>变量说明</strong>： <ul><li>( \\alpha^{\\star} )：最优的参数 ( \\alpha )。</li><li>( \\arg\\max_{\\alpha} )：寻找使 ( \\text{Coverage}(\\alpha) ) 最大的 ( \\alpha )。</li><li>( \\text{Coverage}(\\alpha) )：对应参数 ( \\alpha ) 的选择性覆盖率。</li><li>( \\text{SelErr}(\\alpha) )：对应参数 ( \\alpha ) 的选择性错误率。</li><li>( \\varepsilon )：最大可接受错误，作为硬约束要求选择性错误率不超过 ( \\varepsilon )。</li></ul></li><li><strong>LaTeX 代码</strong>：</li></ul><div class="language-latex line-numbers-mode" data-highlighter="prismjs" data-ext="latex"><pre><code class="language-latex"><span class="line"><span class="token function selector">\\alpha</span>^<span class="token punctuation">{</span><span class="token function selector">\\star</span><span class="token punctuation">}</span> = <span class="token function selector">\\arg</span><span class="token function selector">\\max</span>_<span class="token punctuation">{</span><span class="token function selector">\\alpha</span><span class="token punctuation">}</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>Coverage<span class="token punctuation">}</span>(<span class="token function selector">\\alpha</span>) <span class="token function selector">\\quad</span> <span class="token function selector">\\text</span><span class="token punctuation">{</span>s.t.<span class="token punctuation">}</span> <span class="token function selector">\\ </span><span class="token function selector">\\text</span><span class="token punctuation">{</span>SelErr<span class="token punctuation">}</span>(<span class="token function selector">\\alpha</span>) <span class="token function selector">\\leq</span> <span class="token function selector">\\varepsilon</span></span>
<span class="line"></span></code></pre><div class="line-numbers" aria-hidden="true" style="counter-reset:line-number 0;"><div class="line-number"></div></div></div>`,156)])])}const o=s(l,[["render",i]]),u=JSON.parse('{"path":"/notes/obsidian/%E5%AD%A6%E4%B9%A0/%E5%AD%A6%E6%A0%A1%E7%AB%9E%E8%B5%9B%E3%80%81%E9%A1%B9%E7%9B%AE/%E6%95%B0%E5%AD%A6%E5%BB%BA%E6%A8%A1/%E8%AF%BE%E7%A8%8B%E7%9F%A5%E8%AF%86/%E5%85%AC%E5%BC%8F.html","title":"第二题","lang":"zh-CN","frontmatter":{},"git":{},"filePathRelative":"notes/obsidian/学习/学校竞赛、项目/数学建模/课程知识/公式.md"}');export{o as comp,u as data};
